<template>
  <main class="studio">
    <header class="toolbar">
      <button class="back" @click="router.push('/dashboard')">← 工作台</button><b>智能画图</b>
      <span class="type">当前类型：{{ currentTypeName }}</span>
      <button @click="newFile">新建</button><label class="upload">上传TXT/MD<input type="file" accept=".txt,.md,text/plain,text/markdown" @change="upload" /></label>
      <select v-model="selectedTemplate" @change="insertTemplate"><option value="">插入模板</option><option v-for="item in templates" :key="item.type" :value="item.type">{{ item.name }}</option></select>
      <button type="button" @click="check">检查格式</button><button type="button" class="primary" :disabled="previewLoading||!engineReady" @click="render">{{ previewLoading?'生成中……':'生成预览' }}</button>
      <button :disabled="!detectedHeader.valid" @click="aiGenerate">AI生成</button><button :disabled="!detectedHeader.valid" @click="aiReview">AI检查修复</button><button @click="save">保存项目</button>
    </header>
    <section class="workspace">
      <aside class="left">
        <div class="editor-wrap"><div ref="lineGutter" class="lines">{{ lineNumbers }}</div><textarea ref="editor" v-model="dsl" wrap="off" spellcheck="false" @scroll="syncEditorScroll" @keydown.ctrl.s.prevent="save" @input="markChanged" /></div>
        <div class="checks"><nav><button :class="{on:tab==='local'}" @click="tab='local'">格式检查</button><button :class="{on:tab==='ai'}" @click="tab='ai'">AI建议</button></nav>
          <div v-if="tab==='local'" class="issues"><p v-if="!validation">尚未检查</p><p v-else-if="!validation.issues?.length" class="ok">✓ 格式检查通过</p><button v-for="i in validation?.issues" :key="`${i.line}-${i.code}`" class="issue" @click="goLine(i.line)"><span :class="i.severity">{{ i.severity }}</span><b>第{{ i.line }}行 · {{ i.code }}</b><small>{{ i.message }} {{ i.suggestion }}</small></button></div>
          <div v-else class="issues"><p v-if="!aiResult">AI尚未分析</p><p>{{ aiResult?.summary }}</p><div v-for="(s,index) in aiResult?.suggestions" :key="index" class="issue"><b>{{ s.category || '建议' }}</b><small>{{ s.message }} {{ s.suggestion }}</small></div><button v-if="revisedDsl" class="primary" @click="applyRevision">应用修改</button></div>
        </div>
      </aside>
      <section class="preview" @wheel.prevent="wheelZoom" @pointerdown="startPan" @pointermove="movePan" @pointerup="stopPan" @pointerleave="stopPan"><div v-if="previewLoading" class="preview-state"><span class="spinner"></span><b>{{ previewStatus }}</b></div><div v-else-if="previewError" class="preview-state error-box"><b>预览生成失败</b><span>{{ previewError }}</span><details v-if="previewDetails"><summary>技术详情</summary><pre>{{ previewDetails }}</pre></details></div><div v-else-if="!svg" class="empty">{{ previewStatus || '输入 ThesisDiagram DSL 后生成预览' }}<br><small>语言规范：ThesisDiagram DSL v1.6</small></div><div v-else class="canvas" :style="{transform:`translate(${pan.x}px,${pan.y}px) scale(${zoom})`}" @dblclick="fit" v-html="svg"></div>
        <footer><span class="result-status">{{ previewStatus }}</span><button @click="fit">适应窗口</button><button @click="zoom=Math.min(3,zoom+.1)">＋</button><button @click="zoom=Math.max(.2,zoom-.1)">－</button><button @click="zoom=1">重置</button><span>缩放 {{ Math.round(zoom*100) }}%</span><button :disabled="!exportsReady.svg" @click="download('svg')">下载SVG</button><button :disabled="!exportsReady.json" @click="download('json')">下载JSON</button><button :disabled="!canDownloadPng||pngDownloading" @click="download('png')">{{ pngDownloading?'正在生成PNG……':'下载PNG' }}</button><button @click="vsdx">下载VSDX</button></footer>
      </section>
    </section>
    <div v-if="dialog" class="modal"><div><h3>{{ dialog==='generate'?'AI生成DSL':'AI修订对比' }}</h3><template v-if="dialog==='generate'"><p>当前类型：{{ currentTypeName }}（由编辑器第一条有效行决定）</p><textarea v-model="description" placeholder="请描述需要生成的图形内容" /></template><template v-else><div class="diff"><pre>{{ dsl }}</pre><pre>{{ revisedDsl }}</pre></div></template><footer><button @click="dialog=''">取消</button><button v-if="dialog==='generate'" class="primary" @click="confirmGenerate">生成</button><button v-else class="primary" @click="applyRevision">确认应用</button></footer></div></div>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage } from 'element-plus';
import { validateDiagram,renderDiagram,getDiagramHealth,generateDiagramWithAi,reviewDiagramWithAi,saveDiagramProject,exportDiagram } from '../../api/rewrite'
const router=useRouter(), editor=ref(), lineGutter=ref(), dsl=ref(''), svg=ref(''), validation=ref(), aiResult=ref(), revisedDsl=ref(''), tab=ref('local'), busy=ref(false), previewLoading=ref(false), pngDownloading=ref(false), previewError=ref(''), previewDetails=ref(''), previewStatus=ref(''), exportsReady=ref({svg:false,png:false,json:false,vsdx:false}), engineReady=ref(true), requestSequence=ref(0), dirty=ref(false), zoom=ref(1), pan=ref({x:0,y:0}), drag=ref(null), dialog=ref(''), description=ref(''), selectedTemplate=ref(''), projectId=ref(null)
const templates=[{type:'function_module',name:'三级功能模块图',dsl:'@FunctionModule\n系统：论文管理系统\n模块：用户管理\n功能：注册、登录、权限管理'},{type:'flowchart',name:'标准程序流程图',dsl:'@Flowchart\n标题：业务流程\n[节点]\nN1|start|开始\nN2|process|处理业务\nN3|end|结束\n[连接]\nN1->N2\nN2->N3'},{type:'er_diagram',name:'Chen ER图',dsl:'@ERDiagram\n标题：用户订单ER图\n用户：用户ID(主键)，姓名\n订单：订单ID(主键)，金额\n---\n用户-订单：1*n，创建'},{type:'architecture',name:'系统架构图',dsl:'@ArchitectureDiagram\n标题：系统架构\n层：前端层\n组件：Web应用、移动端\n层：服务层\n组件：业务服务、认证服务'},{type:'use_case',name:'UML用例图',dsl:'@UseCaseDiagram\n标题：系统用例图\n[系统]\nS1|业务系统\n[参与者]\nA1|用户\n[用例]\nU1|S1|登录\n[关联]\nA1->U1\n[用例关系]'},{type:'block_diagram',name:'系统框图',dsl:'@BlockDiagram\n标题：系统框图\n[节点]\nI1|left|输入\nC1|center|处理器\nO1|right|输出\n[连接]\nI1->C1\nC1->O1'},{type:'sequence',name:'UML时序图',dsl:'@SequenceDiagram\n标题：登录时序图\n[参与者]\nA1|actor|用户\nP1|participant|系统\n[消息]\n1|A1->P1|请求登录'}]
const lineNumbers=computed(()=>Array.from({length:Math.max(1,dsl.value.split('\n').length)},(_,i)=>i+1).join('\n'))
const canDownloadPng=computed(()=>typeof svg.value==='string'&&svg.value.includes('<svg'))
const headerNames={'@FunctionModule':'三级功能模块图','@Flowchart':'标准程序流程图','@ERDiagram':'Chen ER图','@ArchitectureDiagram':'系统架构图','@UseCaseDiagram':'UML用例图','@BlockDiagram':'系统框图','@SequenceDiagram':'UML时序图'}
function readHeader(source){const line=String(source||'').replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').split('\n').map(x=>x.trim()).find(x=>x&&!x.startsWith('#')&&!x.startsWith('//'));if(!line)return {valid:false,empty:true,header:''};return {valid:Boolean(headerNames[line]),empty:false,header:line}}
const detectedHeader=computed(()=>readHeader(dsl.value)),currentTypeName=computed(()=>detectedHeader.value.empty?'等待识别':(headerNames[detectedHeader.value.header]||'不支持的图形类型'))
function markChanged(){dirty.value=true;validation.value=null;previewError.value='';if(svg.value)previewStatus.value='代码已修改，预览尚未更新'}
function newFile(){dsl.value='';svg.value='';validation.value=null;previewStatus.value='';exportsReady.value={svg:false,png:false,json:false,vsdx:false};projectId.value=null} function insertTemplate(){const t=templates.find(x=>x.type===selectedTemplate.value);if(t){dsl.value=t.dsl;markChanged()}selectedTemplate.value=''}
async function check(){validation.value=await validateDiagram(dsl.value);tab.value='local';return validation.value} async function render(){if(previewLoading.value)return;const source=dsl.value,seq=++requestSequence.value,controller=new AbortController(),timeoutId=setTimeout(()=>controller.abort(),5000);previewLoading.value=true;previewError.value='';previewDetails.value='';previewStatus.value=`正在生成${currentTypeName.value}……`;exportsReady.value={svg:false,png:false,json:false,vsdx:false};console.info('[diagram-ui] preview click');try{console.info('[diagram-ui] request started');const r=await renderDiagram(source,controller.signal);console.info('[diagram-ui] response status',r?.ok,r?.diagramType);if(seq!==requestSequence.value)return;if(!r?.ok||!r?.svg?.includes('<svg'))throw new Error('绘图接口没有返回有效SVG');validation.value={...r,valid:true};svg.value=r.svg;exportsReady.value=r.exports||{svg:true,png:false,json:true,vsdx:false};dirty.value=false;previewStatus.value=`预览已生成 · ${r.displayName} · ${r.nodeCount||0}个节点 · ${r.durationMs||0}ms`;console.info('[diagram-ui] svg received',r.svg.length);fit();ElMessage.success('预览已生成')}catch(error){if(seq!==requestSequence.value)return;const aborted=controller.signal.aborted;previewError.value=aborted?'预览生成超过5秒，绘图服务可能没有正确连接':(error?.message||'生成预览失败');previewDetails.value=JSON.stringify(error?.responseData||{},null,2);previewStatus.value='预览生成失败';ElMessage.error(previewError.value)}finally{clearTimeout(timeoutId);if(seq===requestSequence.value)previewLoading.value=false}}
function goLine(n){const e=editor.value,lines=dsl.value.split('\n');e.focus();e.setSelectionRange(lines.slice(0,n-1).join('\n').length+(n>1?1:0),lines.slice(0,n).join('\n').length)}
function upload(e){const f=e.target.files?.[0];if(!f)return;if(f.size>1024*1024||!(/\.(txt|md)$/i.test(f.name))){ElMessage.error('仅支持1MB以内TXT或MD');return}const r=new FileReader();r.onload=()=>{dsl.value=String(r.result||'');markChanged()};r.readAsText(f,'UTF-8')}
function aiGenerate(){if(!detectedHeader.value.valid){ElMessage.warning('请先在第一条有效行填写受支持的@头标记');return}dialog.value='generate'} async function confirmGenerate(){busy.value=true;try{const r=await generateDiagramWithAi({dsl:dsl.value,description:description.value});dsl.value=r.dsl||'';dialog.value='';await check()}finally{busy.value=false}}
async function aiReview(){busy.value=true;try{aiResult.value=await reviewDiagramWithAi(dsl.value);revisedDsl.value=aiResult.value.revisedDsl||aiResult.value.revised_dsl||'';tab.value='ai';if(revisedDsl.value)dialog.value='review'}finally{busy.value=false}} function applyRevision(){if(readHeader(revisedDsl.value).header!==detectedHeader.value.header){ElMessage.error('AI_DSL_INVALID：AI修改了图形头标记，已拒绝应用');return}dsl.value=revisedDsl.value;dialog.value='';svg.value='';check()}
async function save(){projectId.value=await saveDiagramProject({id:projectId.value,title:validation.value?.title||'未命名图形',dsl:dsl.value});dirty.value=false;ElMessage.success('项目已保存')}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function svgToPng(source){return new Promise((resolve,reject)=>{try{const parsed=new DOMParser().parseFromString(source,'image/svg+xml'),element=parsed.documentElement;if(element.nodeName.toLowerCase()==='parsererror')throw new Error('SVG内容解析失败');if(!element.getAttribute('xmlns'))element.setAttribute('xmlns','http://www.w3.org/2000/svg');const vb=(element.getAttribute('viewBox')||'').trim().split(/\s+/).map(Number),rawWidth=parseFloat(element.getAttribute('width')),rawHeight=parseFloat(element.getAttribute('height')),width=Number.isFinite(rawWidth)&&rawWidth>0?rawWidth:(vb.length===4&&vb[2]>0?vb[2]:1600),height=Number.isFinite(rawHeight)&&rawHeight>0?rawHeight:(vb.length===4&&vb[3]>0?vb[3]:900),serialized=new XMLSerializer().serializeToString(element),svgBlob=new Blob([serialized],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(svgBlob),image=new Image();image.onload=()=>{try{const scale=2,canvas=document.createElement('canvas');canvas.width=Math.ceil(width*scale);canvas.height=Math.ceil(height*scale);const context=canvas.getContext('2d');if(!context)throw new Error('浏览器无法创建PNG绘图画布');context.fillStyle='#FFFFFF';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('PNG编码失败')),'image/png',1)}catch(error){reject(error)}finally{URL.revokeObjectURL(url)}};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('浏览器加载SVG失败'))};image.src=url}catch(error){reject(error)}})}
function safeFileName(value){return String(value||'ThesisDiagram').replace(/[\\/:*?"<>|]/g,'_').trim()||'ThesisDiagram'}
async function download(format){try{if(format==='png'){if(!canDownloadPng.value)throw new Error('当前没有可转换的SVG预览');pngDownloading.value=true;const name=`${validation.value?.title||'ThesisDiagram'}_${validation.value?.displayName||currentTypeName.value}`;saveBlob(await svgToPng(svg.value),`${safeFileName(name)}.png`);ElMessage.success('PNG已下载');return}saveBlob(await exportDiagram(dsl.value,format),`${safeFileName(validation.value?.title||'diagram')}.${format}`)}catch(error){ElMessage.error(error?.message||`${format.toUpperCase()}下载失败`)}finally{if(format==='png')pngDownloading.value=false}} function vsdx(){ElMessage.info('当前服务器未配置VSDX导出服务')} function fit(){zoom.value=1;pan.value={x:0,y:0}}
function syncEditorScroll(event){if(lineGutter.value)lineGutter.value.scrollTop=event.currentTarget.scrollTop}
function wheelZoom(e){zoom.value=Math.min(3,Math.max(.2,zoom.value+(e.deltaY<0?.1:-.1)))} function startPan(e){if(!svg.value)return;drag.value={x:e.clientX-pan.value.x,y:e.clientY-pan.value.y};e.currentTarget.setPointerCapture?.(e.pointerId)} function movePan(e){if(drag.value)pan.value={x:e.clientX-drag.value.x,y:e.clientY-drag.value.y}} function stopPan(){drag.value=null}
onMounted(async()=>{try{const health=await getDiagramHealth();engineReady.value=Boolean(health?.ok);if(!engineReady.value)previewStatus.value='绘图引擎未就绪，请检查后端 diagram-worker 模块'}catch(error){engineReady.value=false;previewStatus.value='绘图引擎未就绪，请检查后端 diagram-worker 模块';previewError.value=error?.message||previewStatus.value}})
</script>

<style scoped>
*{box-sizing:border-box}.studio{position:fixed;inset:0;display:grid;grid-template-rows:64px minmax(0,1fr);overflow:hidden;background:#f4f7fb;color:#172033}.toolbar{position:sticky;top:0;z-index:8;height:64px;display:flex;align-items:center;gap:9px;padding:0 18px;background:#fff;border-bottom:1px solid #dce4ef;overflow-x:auto;overflow-y:hidden}.toolbar b{font-size:19px;white-space:nowrap}.toolbar .type{color:#64748b;margin-right:auto;white-space:nowrap}button,.upload,select{border:1px solid #d4deeb;background:#fff;border-radius:8px;padding:8px 11px;cursor:pointer;white-space:nowrap}.primary{background:#315efb;color:white;border-color:#315efb}.upload input{display:none}.workspace{height:auto;min-height:0;display:grid;grid-template-columns:minmax(380px,30%) 1fr;gap:12px;padding:12px;overflow:hidden}.left{display:grid;grid-template-rows:65% 35%;min-height:0}.editor-wrap{display:grid;grid-template-columns:45px minmax(0,1fr);background:#111827;border-radius:12px 12px 0 0;overflow:hidden}.lines{height:100%;overflow:hidden;padding:15px 8px;color:#637083;text-align:right;white-space:pre;line-height:22px;font:14px/22px Consolas,'Microsoft YaHei',monospace}.editor-wrap textarea{min-width:0;resize:none;border:0;outline:0;padding:15px;color:#e5e7eb;background:#111827;white-space:pre;overflow:auto;line-height:22px;font:14px/22px Consolas,'Microsoft YaHei',monospace;tab-size:2}.checks{background:#fff;border:1px solid #dae3ef;border-radius:0 0 12px 12px;min-height:0;overflow:auto}.checks nav{position:sticky;top:0;background:#fff;border-bottom:1px solid #e6ebf2}.checks nav button{border:0;border-radius:0}.checks nav .on{color:#315efb;border-bottom:2px solid #315efb}.issues{padding:10px}.issue{display:grid;width:100%;text-align:left;margin-bottom:8px;white-space:normal}.issue small{margin-top:4px;color:#64748b}.error{color:#dc2626}.warning{color:#d97706}.ok{color:#059669}.preview{position:relative;min-width:0;min-height:0;background:#fff;border:1px solid #dae3ef;border-radius:12px;overflow:hidden}.empty{position:absolute;inset:0;display:grid;place-content:center;text-align:center;color:#94a3b8}.canvas{width:100%;height:calc(100% - 52px);display:flex;align-items:center;justify-content:center;transform-origin:center;transition:transform .15s}.canvas :deep(svg){max-width:95%;max-height:95%}.preview>footer{position:absolute;bottom:0;width:100%;height:52px;display:flex;align-items:center;justify-content:center;gap:7px;background:#fff;border-top:1px solid #e4eaf2}.modal{position:fixed;inset:0;background:#0f172a88;display:grid;place-items:center;z-index:10}.modal>div{width:min(900px,90vw);background:#fff;border-radius:14px;padding:20px}.modal textarea{width:100%;height:180px;margin:12px 0;padding:12px}.modal footer{text-align:right}.diff{display:grid;grid-template-columns:1fr 1fr;gap:10px}.diff pre{height:50vh;overflow:auto;background:#111827;color:#e5e7eb;padding:12px;white-space:pre-wrap}@media(max-width:800px){.studio{position:relative;display:block;overflow:auto}.workspace{grid-template-columns:1fr;height:auto;overflow:visible}.left{height:760px}.preview{height:600px}.toolbar{height:auto;min-height:64px;flex-wrap:wrap}.diff{grid-template-columns:1fr}}
.preview-state{position:absolute;inset:0 0 52px;z-index:2;display:grid;place-content:center;gap:12px;text-align:center;background:#ffffffee;color:#64748b}.error-box{color:#b91c1c}.error-box details{max-width:620px;text-align:left;color:#475569}.error-box pre{max-height:180px;overflow:auto;white-space:pre-wrap}.spinner{width:34px;height:34px;margin:auto;border:3px solid #dbe5ff;border-top-color:#315efb;border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.canvas{padding:24px}.canvas :deep(svg){display:block;max-width:100%;max-height:100%;width:auto;height:auto}.result-status{max-width:330px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#64748b}
</style>
